// NEUROMORPH service worker -- app-shell offline support.
//
// Deliberately hand-written rather than generated by a build plugin (this
// project's Vite build can't run in every environment used to edit it --
// see the sandbox notes in OVERNIGHT_PLAN.md -- so a strategy that doesn't
// depend on a build-time precache manifest of hashed filenames is more
// robust here). Strategy:
//   - Navigation requests (loading the app itself): network-first, falling
//     back to the cached shell if offline. Never serve a stale HTML shell
//     while online -- a real network response always wins when available.
//   - Same-origin GET requests for everything else (JS/CSS/fonts/images):
//     stale-while-revalidate -- serve from cache instantly if present while
//     refreshing the cache in the background, so repeat visits feel instant
//     and a flaky connection doesn't block rendering already-seen assets.
//   - Cross-origin requests (Firebase Auth/Firestore, Google Sign-In, the
//     Gemini-backed Cloud Function, Google Fonts) are left completely
//     alone -- never intercepted, never cached. Caching or racing those
//     would risk serving stale auth state or breaking Firestore's realtime
//     listeners, which this app depends on for everything past login.
//   - Non-GET requests (POST/PUT/DELETE) are never intercepted.
//
// Bump CACHE_VERSION whenever you want previously-installed clients to
// pick up a fresh shell after their next navigation.
const CACHE_VERSION = 'v2'; // 2026-08-25: bumped so installed clients pick up the new NEUROMORPH logo/icons
const SHELL_CACHE = `neuromorph-shell-${CACHE_VERSION}`;
const RUNTIME_CACHE = `neuromorph-runtime-${CACHE_VERSION}`;

// Known-stable, always-present files -- safe to precache on install. The
// hashed Vite build output (JS/CSS bundles) is NOT listed here on purpose;
// it gets populated into RUNTIME_CACHE the first time each file is
// actually requested, via the stale-while-revalidate handler below.
const PRECACHE_URLS = [
  '/',
  '/manifest.webmanifest',
  '/favicon.ico',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(PRECACHE_URLS)).catch(() => {
      // A precache failure (e.g. first install while offline) shouldn't
      // block activation -- the runtime cache still fills in as the app
      // is used normally.
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys
          .filter((key) => key !== SHELL_CACHE && key !== RUNTIME_CACHE)
          .map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

function isSameOrigin(url) {
  return new URL(url).origin === self.location.origin;
}

async function networkFirstNavigation(request) {
  try {
    const response = await fetch(request);
    const cache = await caches.open(SHELL_CACHE);
    cache.put('/', response.clone());
    return response;
  } catch {
    const cache = await caches.open(SHELL_CACHE);
    const cached = await cache.match('/');
    return cached || Response.error();
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const networkPromise = fetch(request)
    .then((response) => {
      if (response && response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  return cached || networkPromise || Response.error();
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  if (!isSameOrigin(request.url)) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  // Only cache the kinds of same-origin assets that are safe and useful to
  // reuse offline -- scripts, styles, images, fonts. Anything else
  // (same-origin API-shaped requests, if this app ever adds any) passes
  // through untouched.
  const destination = request.destination;
  if (['script', 'style', 'image', 'font', 'manifest'].includes(destination)) {
    event.respondWith(staleWhileRevalidate(request));
  }
});
